    """Rank the tenant's own records against ``q``."""
    tenant = authenticate(request)
    try:
        return retrieval.query(q, token="", entities=None, limit=limit)
    except retrieval.RetrievalError as exc:
        return {"ok": False, "error": str(exc)}
